// Correction acceptance. Two candidates, K2 and K1.
// K2 uses Z5, the stock half-press poke, and the same menu keys as the candidates.
// The save is the T5 menu commit then the menu exit. Completion status is the
// NAND return d0 or the callback d0. Do not edit this file after it has run.
// Usage: node26 work/scripts/accept_v1.mjs om-emu
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runZone } from '../../ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/zone_session_k1.mjs';
import { applyStep } from '../../ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/observe_c1.mjs';
import { attachPose } from '../../ref/tasks/T7-orientation-producer/run-20261119-072701/work/scripts/pose.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/accept_v1.mjs om-emu\n');
  process.exit(2);
}

const Z5 = 'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/overlay-changed-bytes-c1.csv';
const T6 = 'work/out/overlay-changed-bytes.csv';
const sourceTable = JSON.parse(readFileSync(
  resolve('ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/accept_table_c3.json'),
  'utf8',
));
const menuSteps = sourceTable.filter((step) =>
  (step.phase === 'menu-a' || step.phase === 'menu-b')
  && (step.who === 'candidate' || step.who === 'both')
  && step.action !== 'save' && step.action !== 'edge'
  && step.action !== 'reopen-base' && step.action !== 'reopen-edge');
for (const step of menuSteps) {
  const cells = step.expect && step.expect.readback && step.expect.readback.cells;
  if (cells && Array.isArray(cells.k1dd1)) cells.k1dd1 = [3, 3, 3, 3, 3, 3, 3, 3, 3, 3];
}
writeFileSync(resolve('work/out/accept-table-v1.json'), JSON.stringify(menuSteps, null, 2) + '\n');

const EDGES = [
  ['s1', 'down'], ['s1', 'up'],
  ['afon', 'down'], ['afon', 'up'],
  ['s1', 'down'], ['afon', 'down'], ['afon', 'up'], ['s1', 'up'],
  ['afon', 'down'], ['s1', 'down'], ['s1', 'up'], ['afon', 'up'],
];
const OWNERS = [1, 0, 2, 0, 1, 2, 1, 0, 2, 2, 2, 0];
const AFON = new Set([2, 5, 8, 9, 10]);
const ALL = [0x0e, 0x02, 0x02, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00];
const SMALL = [0x11, 0x02, 0x03, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00];
const C1 = [0x1c, 0x02, 0x07, 0x00, 0x05, 0x00, 0x07, 0x00, 0x00, 0x00];
const HALF3 = [0x0e, 0x02, 0x03, 0x00, 0x03, 0x00, 0x03, 0x00, 0x00, 0x00];
const STOCK = [0x0e, 0x02, 0x02, 0x00, 0x1b, 0x00, 0x27, 0x00, 0x00, 0x00];
const GET = 0x60063380;
const SET = 0x60063431;
const MIRROR = 0xa031eeb0;
const MIRROR_C = 0x6031eeb0;
const ZONE = 0xa031e920;
const POSE = 0xa32c568c;
const RET_ZONE = 0x60a8f71c;
const RET_SIZE = 0x60a8f757;
const RET_POS = 0x60a8f76e;
const RET_PLUS9 = 0x60a8f789;
const CALL_CONV = 0x60a8f71f;
const BACK_CONV = 0x60a8f726;
const HALF = {
  k99a1: [0, 0, 2, 0, 2, 0, 5, 5], k9a41: 0, k84d1: 2, k88b2: 526,
  k5962: [526, 526, 526, 526, 526, 526],
  k1dd1: [1, 1, 3, 3, 3, 3, 3, 3, 3, 3],
  k1df1: [1, 1, 1, 1, 0, 0, 0, 0], k1e01: 0, kdfa1: 0,
  k99d2: [526, 526, 526], k90a1: [1, 1], k1db1: 1, k1dc1: 1,
};
const FACTORY = {
  k99a1: [2, 0, 2, 0, 2, 0, 5, 5], k9a41: 0, k84d1: 3, k88b2: 526,
  k5962: [526, 526, 526, 526, 526, 526],
  k1dd1: [3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
  k1df1: [1, 1, 1, 1, 0, 0, 0, 0], k1e01: 0, kdfa1: 0,
  k99d2: [526, 526, 526], k90a1: [1, 1], k1db1: 1, k1dc1: 1,
};

const OUT = resolve('work/out/accept-v1.jsonl');
const lines = [];
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify({ id: row.id, pass: row.pass, problems: row.problems || null }));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const holder = { events: [], queue: [] };

function put(m, off, value) { m[off] = value & 0xff; m[off + 1] = (value >> 8) & 0xff; }
function mirrorA() {
  const m = new Uint8Array(55);
  m[1] = 2;
  put(m, 0x0c, 529);
  put(m, 0x22, 529);
  return Array.from(m);
}
function mirrorB() {
  const m = Uint8Array.from(mirrorA());
  m[5] = 6;
  put(m, 0x14, 540);
  m[0x18] = 5;
  m[0x19] = 7;
  return Array.from(m);
}

function cellView(got) {
  return {
    k90a1: got.cells.k90a1, k1dd1: got.cells.k1dd1, k99a1: got.cells.k99a1,
    k9a41: got.cells.k9a41, k5962: got.cells.k5962, home: got.cells.home,
    originally: got.invariant.originally,
  };
}
function judgeMenu(step, got, previous) {
  const exp = step.expect;
  const rb = exp.readback || {};
  const problems = [];
  if (exp.assertTitle !== false && got.title !== exp.title) problems.push('title');
  if (got.helpText !== exp.helpText) problems.push('helpText');
  if (got.highlight !== exp.highlight) problems.push('highlight');
  if (got.screen !== rb.screen) problems.push('screen');
  if (got.profile !== rb.profile) problems.push('profile');
  if (got.profileCached !== rb.profileCached) problems.push('profileCached');
  if (!same(got.invariant.k90a1, rb.k90a1)) problems.push('k90a1');
  if (exp.assertFaces !== false) {
    if (got.slotValue !== rb.slotValue) problems.push('slotValue');
    if (got.helpId !== rb.helpId) problems.push('helpId');
  }
  if (exp.assertGlyph !== false && !same(got.glyph, rb.glyph)) problems.push('glyph');
  if (exp.headerHash && got.headerHash !== exp.headerHash) problems.push('header');
  if (rb.cells && !same(cellView(got), rb.cells)) problems.push('cells');
  if (exp.invariant && previous && !same(got.invariant, previous)) problems.push('invariant');
  return problems;
}
function expectedMenu(step) {
  const exp = step.expect;
  const rb = exp.readback || {};
  return {
    title: exp.title, helpText: exp.helpText, highlight: exp.highlight,
    screen: rb.screen, profile: rb.profile, profileCached: rb.profileCached,
    k90a1: rb.k90a1, slotValue: rb.slotValue, helpId: rb.helpId, glyph: rb.glyph,
    headerHash: exp.headerHash ?? null, cells: rb.cells ?? null,
  };
}
function actualMenu(got) {
  return {
    title: got.title, helpText: got.helpText, highlight: got.highlight,
    screen: got.screen, profile: got.profile, profileCached: got.profileCached,
    k90a1: got.invariant.k90a1, slotValue: got.slotValue, helpId: got.helpId,
    glyph: got.glyph, headerHash: got.headerHash, cells: cellView(got),
    screenshot: got.screenshot,
  };
}

function readKey(ctx, key, index) {
  return ctx.l.call(ctx.native(GET), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff;
}
function setKey(ctx, key, index, value) {
  ctx.l.call(ctx.native(SET), { d0: key, d1: index, a1: value }, null, null, 200000);
  if (readKey(ctx, key, index) !== (value & 0xffff)) throw new Error('setter readback');
}
function half(ctx) {
  return {
    k99a1: Array.from({ length: 8 }, (_, i) => readKey(ctx, 0x99a1, i)),
    k9a41: readKey(ctx, 0x9a41, 0), k84d1: readKey(ctx, 0x84d1, 0), k88b2: readKey(ctx, 0x88b2, 0),
    k5962: Array.from({ length: 6 }, (_, i) => readKey(ctx, 0x5962, i)),
    k1dd1: Array.from({ length: 10 }, (_, i) => readKey(ctx, 0x1dd1, i)),
    k1df1: Array.from({ length: 8 }, (_, i) => readKey(ctx, 0x1df1, i)),
    k1e01: readKey(ctx, 0x1e01, 0), kdfa1: readKey(ctx, 0xdfa1, 0),
    k99d2: [0, 1, 2].map((i) => readKey(ctx, 0x99d2, i)),
    k90a1: [readKey(ctx, 0x90a1, 0), readKey(ctx, 0x90a1, 1)],
    k1db1: readKey(ctx, 0x1db1, 0), k1dc1: readKey(ctx, 0x1dc1, 0),
  };
}
function mirrorBytes(ctx) { return Array.from(ctx.l.sim.read(MIRROR, 55)); }
function seed(ctx, bytes) {
  const buf = Buffer.from(bytes);
  ctx.l.sim.write(MIRROR, buf);
  ctx.l.sim.write(MIRROR_C, buf);
}
function pokeAll(ctx) {
  setKey(ctx, 0x84d1, 0, 2);
  setKey(ctx, 0x1dd1, 0, 1);
  setKey(ctx, 0x1dd1, 1, 1);
  setKey(ctx, 0x99a1, 0, 0);
}
function restoreFactory(ctx) {
  setKey(ctx, 0x84d1, 0, 3);
  setKey(ctx, 0x1dd1, 0, 3);
  setKey(ctx, 0x1dd1, 1, 3);
  setKey(ctx, 0x99a1, 0, 2);
}
function linkOn(ctx) {
  setKey(ctx, 0x1db1, 0, 1);
  setKey(ctx, 0x1dc1, 0, 1);
}
function install(ctx) {
  const link = { area: 0, pos: 0 };
  let inConv = false;
  const counts = { zone: 0, size: 0, pos: 0, plus9: 0, dim: 0 };
  const u8 = (a) => ctx.l.sim.read(a, 1)[0];
  const u16 = (a) => { const b = ctx.l.sim.read(a, 2); return b[0] | (b[1] << 8); };
  const bank = () => {
    if (!(link.area === 1 && link.pos === 1)) return 1;
    const pose = ctx.l.sim.u32(POSE) >>> 0;
    if (pose === 2) return 5;
    if (pose === 4) return 3;
    return 1;
  };
  const refresh = () => {
    link.area = readKey(ctx, 0x1db1, 0);
    link.pos = readKey(ctx, 0x1dc1, 0);
  };
  ctx.l.observe(ctx.native(CALL_CONV), () => { inConv = true; }, 'obs-builder-converter');
  ctx.l.observe(ctx.native(BACK_CONV), () => { inConv = false; }, 'obs-builder-converter-back');
  ctx.l.hook(ctx.native(GET), (h, r) => {
    const back = r.mdr >>> 0;
    const key = r.d0 & 0xffff;
    const index = r.d1 & 0xffff;
    const b = bank();
    if (back === RET_ZONE) {
      counts.zone += 1;
      let v = u8(MIRROR + b);
      if (v === 0xff) v = u8(ZONE);
      h.finish(r, { d0: v });
      return;
    }
    if (back === RET_SIZE) {
      counts.size += 1;
      let v = u8(MIRROR + 0x08);
      if (v === 0xff) v = 0;
      h.finish(r, { d0: v });
      return;
    }
    if (back === RET_POS) {
      counts.pos += 1;
      let v = u16(MIRROR + 0x0a + b * 2);
      if (v === 0xffff) v = 0;
      h.finish(r, { d0: v });
      return;
    }
    if (back === RET_PLUS9) { counts.plus9 += 1; h.finish(r, { d0: 0 }); return; }
    if (inConv && key === 0x1dd1) {
      counts.dim += 1;
      let v = u8(MIRROR + 0x16 + (index & 0xff));
      if (v === 0xff) v = 0;
      h.finish(r, { d0: v });
      return;
    }
    ctx.l.passthrough(r);
  }, 'EMULATOR-ONLY profile read from the mirror. Role: behaviour.');
  return { refresh, counts };
}

async function prepare(ctx) {
  const { A } = await import(pathToFileURL(resolve(checkout, 'emu/src/fw/model.mjs')).href);
  const api = A(0x50ac4afe);
  const brought = ctx.bringUp();
  ctx.emit('behaviour', {
    step: 'bring-up',
    label: 'EMULATOR-ONLY native bring-up 0x6071181e, 0x608fe1b0, 0x609df7e4, task 105. Role: behaviour.',
    ...brought,
  });
  ctx.s.switch_input('lever', 1);
  ctx.s.camapp.pump();
  ctx.idle(500);
  const argument = ctx.l.call(ctx.native(0x604050e5), { d0: 289, d1: 0 }, null, null, 200000).d0 >>> 0;
  ctx.l.call(api, { d0: 289, d1: argument }, null, null, 200000);
  ctx.l.call(api, { d0: 1712, d1: 0 }, null, null, 200000);
  ctx.idle(500);
  const subject = readKey(ctx, 0x1e71, 0);
  if (subject !== 0) throw new Error('subject ' + subject);
  if (ctx.s.get(289) !== 0 || ctx.s.get(25) !== 0) throw new Error('focus');
  return { subject, focus: ctx.s.get(289), active: ctx.s.get(25) };
}

async function installWitness() {
  process.env.OM_EMU_MODEL = 'E147';
  const menu = await import(pathToFileURL(resolve(checkout, 'emu/src/lab/menu.mjs')).href);
  const proto = menu.MenuLab.prototype;
  if (proto.__saveWitness) return;
  const orig = proto._s_nand_write;
  proto._s_nand_write = function(hle, r, posted) {
    const before = this.store_log && this.store_log.nvram ? this.store_log.nvram.saves.length : 0;
    const origAfter = hle.finish_after.bind(hle);
    const origFinish = hle.finish.bind(hle);
    const rec = {
      store: null, from: null, posted: !!posted, via: null,
      intended: null, status: null, callback: null,
    };
    hle.finish_after = (regs, fn, args) => {
      rec.via = 'callback';
      rec.intended = args.d0 >>> 0;
      rec.callback = fn >>> 0;
      holder.queue.push(rec);
      this.observe(fn, (lab, rr) => {
        const job = holder.queue.shift();
        if (job) job.status = rr.d0 >>> 0;
      }, 'obs-save-cb-' + (fn >>> 0).toString(16));
      return origAfter(regs, fn, args);
    };
    hle.finish = (regs, args = {}) => {
      if (rec.via === null) {
        rec.via = 'return';
        rec.intended = (args.d0 ?? 0) >>> 0;
        rec.status = rec.intended;
      }
      return origFinish(regs, args);
    };
    try {
      return orig.call(this, hle, r, posted);
    } finally {
      hle.finish_after = origAfter;
      hle.finish = origFinish;
      const saves = this.store_log && this.store_log.nvram ? this.store_log.nvram.saves : null;
      if (saves && saves.length > before) {
        const row = saves[saves.length - 1];
        rec.store = row.store;
        rec.from = row.from;
        rec.posted = !!row.posted;
        holder.events.push(rec);
      }
    }
  };
  proto.__saveWitness = true;
}

function check(id, problems, extra) {
  emit({ id, pass: problems.length === 0, problems, ...extra });
  if (problems.length) throw new Error(id + ' ' + problems.join(','));
}

function edgeExpect(profile, phase, index) {
  if (!profile) return ALL;
  return AFON.has(index) ? (phase === 'b' ? C1 : SMALL) : ALL;
}

async function runEdges(ctx, name, phase, profile, hook, mirror) {
  for (let i = 0; i < EDGES.length; i++) {
    if (hook) hook.refresh();
    ctx.key(EDGES[i][0], EDGES[i][1]);
    ctx.idle(250);
    const id = name + '-' + phase + '-e' + i;
    const shot = ctx.shot(id);
    const own = ctx.readOwn();
    const target = ctx.readTarget();
    const want = edgeExpect(profile, phase, i);
    const nowHalf = half(ctx);
    const nowMirror = mirrorBytes(ctx);
    const focus = ctx.s.get(289);
    const active = ctx.s.get(25);
    const problems = [];
    if (!same(target, want)) problems.push('target');
    if (own[4] !== OWNERS[i]) problems.push('owner');
    if (own[5] !== 0) problems.push('status');
    if (own[6] !== 1) problems.push('enabled');
    if (focus !== 0 || active !== 0) problems.push('focus');
    if (readKey(ctx, 0x1e71, 0) !== 0) problems.push('subject');
    if (!same(nowHalf, HALF)) problems.push('half');
    if (profile && !same(nowMirror, mirror)) problems.push('mirror');
    if (!profile && nowMirror.some((b) => b !== 0xff)) problems.push('mirror-seeded');
    check(id, problems, {
      step: 'edge', key: EDGES[i][0], dir: EDGES[i][1],
      expected: { target: want, owner: OWNERS[i], status: 0, enabled: 1, focus: 0, active: 0, half: HALF, mirror },
      actual: {
        target, owner: own[4], status: own[5], enabled: own[6], focus, active,
        subject: readKey(ctx, 0x1e71, 0), half: nowHalf, mirror: nowMirror,
        screenshot: shot.file.split(/[/\\]/).pop(),
      },
    });
  }
}

async function runMenu(ctx, name) {
  let previous = null;
  for (const step of menuSteps) {
    const got = await applyStep(ctx, step);
    const id = name + '-' + step.id;
    const problems = judgeMenu(step, got, previous);
    check(id, problems, {
      step: 'key', key: step.key, action: step.action,
      expected: expectedMenu(step), actual: actualMenu(got),
    });
    previous = got.invariant;
  }
  ctx.idle(800);
  const log = ctx.l.store_log.nvram.saves.map((rec) => ({
    store: rec.store, from: rec.from, posted: rec.posted,
  }));
  const events = holder.events.map((ev) => ({ ...ev }));
  const problems = [];
  for (const storeName of ['M', 'E']) {
    if (!log.some((rec) => rec.store === storeName)) problems.push('log-' + storeName);
    const rows = events.filter((ev) => ev.store === storeName);
    if (!rows.length) problems.push('witness-' + storeName);
    if (rows.some((ev) => ev.status !== 0)) problems.push(storeName + '-status');
  }
  const postedM = events.filter((ev) => ev.store === 'M' && ev.posted);
  if (!postedM.length || postedM.some((ev) => ev.status !== 0)) problems.push('menu-M');
  if (events.some((ev) => ev.status === null)) problems.push('callback-pending');
  check(name + '-save', problems, {
    step: 'save',
    expected: { stores: ['M', 'E'], status: 0, postedM: true },
    actual: { log, events, screen: ctx.s.screen() },
  });
}

async function session(name, role) {
  const profile = role === 'candidate';
  const z5 = role !== 'k1';
  const nv = 'work/out/nvram-accept-v1-' + name + '.json';
  holder.events = [];
  holder.queue = [];
  const result = await runZone({
    checkout,
    outPath: 'work/out/session-accept-v1-' + name + '.jsonl',
    tag: 'accept-v1-' + name,
    candidate: z5,
    help: true,
    rowLabel: true,
    fatalShots: true,
    nvramPath: nv,
    overlayCsv: profile ? T6 : (z5 ? Z5 : null),
    explanation: profile
      ? name + ' acceptance. Profile A, pose, profile B, T5 save. EMULATOR-ONLY. Role: behaviour.'
      : (z5
        ? name + ' K2. Z5, same poke and the same menu keys, no mirror seed.'
        : name + ' K1. Stock. Landscape edges only. No AF-ON row.'),
    change: profile ? 'combined profile read, already in the overlay' : 'none',
    async drive(ctx) {
      const hook = profile ? install(ctx) : null;
      const setup = await prepare(ctx);
      check(name + '-setup-focus', [], {
        step: 'setup', expected: { subject: 0, focus: 0, active: 0 }, actual: setup,
      });
      if (!z5) {
        for (let i = 0; i < EDGES.length; i++) {
          ctx.key(EDGES[i][0], EDGES[i][1]);
          ctx.idle(250);
          const id = name + '-a-e' + i;
          const shot = ctx.shot(id);
          const target = ctx.readTarget();
          const problems = [];
          if (!same(target, STOCK)) problems.push('target');
          if (ctx.s.get(289) !== 0 || ctx.s.get(25) !== 0) problems.push('focus');
          if (readKey(ctx, 0x1e71, 0) !== 0) problems.push('subject');
          check(id, problems, {
            step: 'edge', key: EDGES[i][0], dir: EDGES[i][1],
            expected: { target: STOCK, focus: 0, active: 0, subject: 0 },
            actual: {
              target, focus: ctx.s.get(289), active: ctx.s.get(25),
              subject: readKey(ctx, 0x1e71, 0), mirror: mirrorBytes(ctx),
              screenshot: shot.file.split(/[/\\]/).pop(),
            },
          });
        }
        return;
      }
      const pose = attachPose(ctx.l);
      pose.setPose('landscape');
      pose.deliver();
      ctx.idle(600);
      linkOn(ctx);
      const before = half(ctx);
      const factoryProblems = [];
      if (before.k84d1 !== 3 || before.k1dd1[0] !== 3 || before.k1dd1[1] !== 3 || before.k99a1[0] !== 2) {
        factoryProblems.push('factory');
      }
      check(name + '-factory', factoryProblems, {
        step: 'factory', expected: { k84d1: 3, d0: 3, d1: 3, area: 2 }, actual: before,
      });
      pokeAll(ctx);
      let mirror = null;
      if (profile) {
        mirror = mirrorA();
        seed(ctx, mirror);
      }
      if (hook) hook.refresh();
      const setupProblems = [];
      if (!same(half(ctx), HALF)) setupProblems.push('half');
      if (profile && !same(mirrorBytes(ctx), mirror)) setupProblems.push('mirror');
      if (pose.read().index !== 1 || pose.read().exif !== 1) setupProblems.push('pose');
      check(name + '-setup', setupProblems, {
        step: 'setup', expected: { half: HALF, mirror, pose: { index: 1, exif: 1 } },
        actual: { half: half(ctx), mirror: mirrorBytes(ctx), pose: pose.read() },
      });
      await runEdges(ctx, name, 'a', profile, hook, mirror);
      pose.setPose('exif6');
      pose.deliver();
      ctx.idle(600);
      linkOn(ctx);
      pokeAll(ctx);
      if (profile) {
        mirror = mirrorB();
        seed(ctx, mirror);
      }
      if (hook) hook.refresh();
      const poseGot = pose.read();
      const poseProblems = [];
      if (poseGot.index !== 2 || poseGot.exif !== 6) poseProblems.push('pose');
      if (!same(half(ctx), HALF)) poseProblems.push('half');
      if (profile && !same(mirrorBytes(ctx), mirror)) poseProblems.push('mirror');
      if ((ctx.l.sim.u32(POSE) >>> 0) !== 2) poseProblems.push('word');
      check(name + '-pose', poseProblems, {
        step: 'pose',
        expected: { index: 2, exif: 6, word: 2, half: HALF, mirror },
        actual: { pose: poseGot, word: ctx.l.sim.u32(POSE) >>> 0, half: half(ctx), mirror: mirrorBytes(ctx) },
      });
      await runEdges(ctx, name, 'b', profile, hook, mirror);
      restoreFactory(ctx);
      const restored = half(ctx);
      const restoreProblems = [];
      if (!same(restored, FACTORY)) restoreProblems.push('factory');
      if (ctx.readByte(ZONE) !== 0) restoreProblems.push('zone');
      check(name + '-restore', restoreProblems, {
        step: 'restore', expected: { half: FACTORY, zone: 0 }, actual: { half: restored, zone: ctx.readByte(ZONE) },
      });
      await runMenu(ctx, name);
      if (hook && hook.counts.dim === 0) throw new Error(name + ' custom dimensions were not read');
    },
  });
  if (!result.ok) throw new Error(name + ' ' + result.failed);
  return nv;
}

function decode(file) {
  const doc = JSON.parse(readFileSync(resolve(file), 'utf8'));
  const out = {};
  for (const storeName of ['M', 'E']) {
    const raw = Buffer.from(doc[storeName], 'base64');
    out[storeName] = raw;
  }
  return out;
}
function diffOffsets(a, b) {
  const n = Math.max(a.length, b.length);
  const offsets = [];
  for (let i = 0; i < n; i++) if (a[i] !== b[i]) offsets.push(i);
  return offsets;
}

async function reopen(name, role, nv) {
  const profile = role === 'candidate';
  const z5 = role !== 'k1';
  holder.events = [];
  holder.queue = [];
  const result = await runZone({
    checkout,
    outPath: 'work/out/session-accept-v1-' + name + '-reopen.jsonl',
    tag: 'accept-v1-' + name + '-reopen',
    candidate: z5,
    help: true,
    rowLabel: true,
    fatalShots: true,
    nvramPath: nv,
    overlayCsv: profile ? T6 : (z5 ? Z5 : null),
    explanation: name + ' reopen on the saved store. EMULATOR-ONLY. Role: behaviour.',
    change: profile ? 'combined profile read, already in the overlay' : 'none',
    async drive(ctx) {
      const hook = profile ? install(ctx) : null;
      await prepare(ctx);
      const mirror = mirrorBytes(ctx);
      const baseTarget = ctx.readTarget();
      const baseShot = ctx.shot(name + '-reopen-base');
      const baseProblems = [];
      if (ctx.s.screen() !== 'shooting') baseProblems.push('screen');
      if (readKey(ctx, 0x1e71, 0) !== 0) baseProblems.push('subject');
      if (mirror.some((b) => b !== 0xff)) baseProblems.push('mirror');
      if (z5 && ctx.readByte(ZONE) !== 0) baseProblems.push('zone');
      if (!same(baseTarget, STOCK)) baseProblems.push('target');
      check(name + '-reopen-base', baseProblems, {
        step: 'reopen-base',
        expected: { screen: 'shooting', subject: 0, zone: z5 ? 0 : null, mirror: 'FF', target: STOCK },
        actual: {
          screen: ctx.s.screen(), subject: readKey(ctx, 0x1e71, 0), zone: ctx.readByte(ZONE),
          mirror, target: baseTarget, focus: ctx.s.get(289), active: ctx.s.get(25),
          screenshot: baseShot.file.split(/[/\\]/).pop(),
        },
      });
      const pressWant = z5 ? ALL : STOCK;
      const releaseWant = z5 ? HALF3 : STOCK;
      for (const [dir, want, owner] of [['down', pressWant, 2], ['up', releaseWant, 0]]) {
        ctx.key('afon', dir);
        ctx.idle(250);
        const id = name + '-reopen-afon-' + dir;
        const shot = ctx.shot(id);
        const own = ctx.readOwn();
        const target = ctx.readTarget();
        const problems = [];
        if (!same(target, want)) problems.push('target');
        if (z5 && own[4] !== owner) problems.push('owner');
        if (z5 && own[5] !== 0) problems.push('status');
        if (z5 && own[6] !== 1) problems.push('enabled');
        if (mirrorBytes(ctx).some((b) => b !== 0xff)) problems.push('mirror');
        if (readKey(ctx, 0x1e71, 0) !== 0) problems.push('subject');
        check(id, problems, {
          step: 'reopen-edge', key: 'afon', dir,
          expected: { target: want, owner: z5 ? owner : null, status: z5 ? 0 : null, enabled: z5 ? 1 : null, mirror: 'FF' },
          actual: {
            target, owner: own[4], status: own[5], enabled: own[6],
            focus: ctx.s.get(289), active: ctx.s.get(25),
            subject: readKey(ctx, 0x1e71, 0), mirror: mirrorBytes(ctx),
            screenshot: shot.file.split(/[/\\]/).pop(),
          },
        });
      }
      if (hook) {
        emit({
          id: name + '-reopen-hook', step: 'hook', pass: true,
          counts: hook.counts,
          fallback: 'mirror FF uses zone byte 0, size 0, position 0, +9 0. Kind 2 forces position 526. The press record is All.',
        });
      }
    },
  });
  if (!result.ok) throw new Error(name + ' reopen ' + result.failed);
}

emit({
  id: 'accept-v1-plan', step: 'plan', pass: true,
  fallback: 'Uninitialised mirror uses zone byte 0, size 0, position 0 and +9 0. Kind 2 then forces 526. AF-ON press is All. Release restores the stock half-press record 0e 02 03 00 03 00 03 00 00 00.',
  k1: 'K1 is stock and has no AF-ON row. It runs the landscape 12 edges and the reopen press and release. It does not run the chooser.',
  small: SMALL, c1: C1, all: ALL, half3: HALF3, stock: STOCK,
});

try {
  await installWitness();
  const files = {};
  for (const [name, role] of [['k2', 'k2'], ['c1', 'candidate'], ['c2', 'candidate'], ['k1', 'k1']]) {
    files[name] = await session(name, role);
  }
  const k2store = decode(files.k2);
  for (const name of ['c1', 'c2']) {
    const store = decode(files[name]);
    const diffs = {
      M: diffOffsets(store.M, k2store.M),
      E: diffOffsets(store.E, k2store.E),
    };
    const problems = [];
    if (diffs.M.length || diffs.E.length) problems.push('store');
    if (store.M.length !== 262144 || store.E.length !== 196608) problems.push('length');
    check(name + '-store', problems, {
      step: 'store',
      expected: { mDiffs: [], eDiffs: [], mBytes: 262144, eBytes: 196608 },
      actual: {
        mDiffs: diffs.M, eDiffs: diffs.E, mBytes: store.M.length, eBytes: store.E.length,
        mSha256: createHash('sha256').update(store.M).digest('hex'),
        eSha256: createHash('sha256').update(store.E).digest('hex'),
      },
    });
  }
  for (const [name, role] of [['k2', 'k2'], ['c1', 'candidate'], ['c2', 'candidate'], ['k1', 'k1']]) {
    await reopen(name, role, files[name]);
  }
  emit({ id: 'accept-v1-done', step: 'done', pass: true, ok: true });
} catch (error) {
  emit({ id: 'accept-v1-done', step: 'done', pass: false, ok: false, error: String(error && error.stack ? error.stack : error) });
  process.exit(1);
}
